'use client'
import { cn, useControllableSignal, useSignalEffect, useSignals } from '@cascivo/core'
import type { SpaceStep } from '@cascivo/core'
import { cloneElement, isValidElement, useRef } from 'react'
import type { HTMLAttributes, ReactElement, ReactNode } from 'react'
import styles from './app-shell.module.css'

/** Props AppShell injects into a {@link ShellHeader}-shaped header element. */
interface HeaderMenuProps {
  onMenuClick?: (() => void) | undefined
  menuExpanded?: boolean
}

/**
 * `AppShell` extends `HTMLAttributes<HTMLDivElement>`, like every other layout primitive,
 * so `className` **and `style`** pass through to its root element. That matters because the
 * shell's documented design tokens (`--cascivo-shell-aside-inline-size`,
 * `--cascivo-shell-panel-inline-size`, `--cascivo-shell-header-block-size`) have to be set
 * *somewhere*: set them here —
 * `<AppShell style={{ '--cascivo-shell-aside-inline-size': '15.5rem' }}>` — or on any
 * ancestor, since they inherit. Before this the props were a closed list with no `style`,
 * so the tokens had no documented application point and adopters set them on `#root`.
 */
export interface AppShellProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * Top bar — typically a `<ShellHeader>`. If it is a React element, AppShell
   * binds its burger (`onMenuClick`/`menuExpanded`) to the nav open state so the
   * header button toggles the nav out of the box.
   */
  header: ReactNode
  /** Side navigation — typically a `<SideNav>`. Fills full height and scrolls internally. */
  nav?: ReactNode
  /** Main content. Lives in the single scroll container. */
  children: ReactNode
  /** Optional footer pinned below the content area. */
  footer?: ReactNode
  /** Controlled nav open/visible state. Omit for uncontrolled (see `defaultOpen`). */
  open?: boolean
  /** Initial open state when uncontrolled. Defaults to open on desktop, closed on small screens. */
  defaultOpen?: boolean
  /** Fired when the nav requests open/close (burger, Escape, scrim). */
  onOpenChange?: ((open: boolean) => void) | undefined
  /**
   * Inset around the main content area, as a space-scale step.
   *
   * ⚠ It **defaults to `6`**, not to none. `<main>` shipped with `padding: 0` for three
   * releases, so every adopter wrote the same wrapper `<div style={{ padding: … }}>` and
   * every app's first screenshot had its buttons clipped against the viewport edge — the CLI's
   * own generated dashboard modelled the workaround with an inline style its sibling
   * AGENTS.md forbids. Reported three times (2026-07-24, 2026-08-06, 2026-08-08).
   *
   * Pass `'none'` for a full-bleed layout that owns its own insets (a map, a split pane).
   *
   * @defaultValue `6`
   */
  padding?: SpaceStep | 'none'
  className?: string | undefined
}

/**
 * App shell: composes a header + side navigation + main content into one
 * sticky-header, full-height-nav, single-scroll-container layout (#11). The
 * header burger toggles the nav with an animated show/hide that honors
 * `prefers-reduced-motion` (via `--cascivo-motion-*`), toggles `inert` on the
 * hidden nav so it leaves the tab order, and renders a mobile drawer + scrim
 * (#12). Below `lg` (64rem) the nav is an overlay drawer; at `lg`+ it is an
 * in-flow column whose width animates between its open width and 0.
 *
 * Rail vs full-hide reconcile cleanly: AppShell owns the full show/hide (this
 * `open` state); the SideNav you pass owns its own rail collapse
 * (`showCollapseToggle`). They compose on different axes and never fight.
 *
 * **Visual regression note:** the shell is `100dvh` with an internal scroll container (that
 * is what makes the header sticky and the nav full-height). The page body therefore never
 * grows, so a Playwright `fullPage: true` screenshot captures only the viewport. To capture
 * the whole page, screenshot the scroll container element or set a tall viewport.
 */
export function AppShell({
  header,
  nav,
  children,
  footer,
  open,
  defaultOpen,
  onOpenChange,
  padding = 6,
  className,
  ...props
}: AppShellProps) {
  useSignals()
  const controlled = open !== undefined
  // Controlled mirror goes through the shared primitive: a bare `sig.value = prop` in render
  // notifies the previous render's subscriptions, which React 19 reports as a setState during
  // render (2026-08-08 report A). The primitive skips the write when the value is unchanged.
  const [isOpen] = useControllableSignal<boolean>({
    value: open,
    defaultValue: defaultOpen ?? true,
  })

  const navWrapperRef = useRef<HTMLDivElement>(null)
  const toggleOriginRef = useRef<HTMLElement | null>(null)

  function setOpen(next: boolean) {
    if (!controlled) isOpen.value = next
    onOpenChange?.(next)
  }
  function toggle() {
    if (typeof document !== 'undefined') {
      toggleOriginRef.current = document.activeElement as HTMLElement | null
    }
    setOpen(!isOpen.value)
  }

  // Uncontrolled: start closed on small screens so the drawer isn't open on load.
  useSignalEffect(() => {
    if (controlled || defaultOpen !== undefined) return
    if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return
    if (window.matchMedia('(max-width: 63.999rem)').matches) isOpen.value = false
  })

  // Escape closes the nav (drawer) — read the signal so the effect re-subscribes.
  useSignalEffect(() => {
    if (!isOpen.value || typeof document === 'undefined') return
    const onKey = (e: globalThis.KeyboardEvent) => {
      if (e.key === 'Escape') setOpen(false)
    }
    document.addEventListener('keydown', onKey)
    return () => document.removeEventListener('keydown', onKey)
  })

  // inert + focus management: when closed the nav leaves the tab order; on the
  // mobile drawer, move focus in on open and restore it to the toggle on close.
  useSignalEffect(() => {
    const wrapper = navWrapperRef.current
    if (!wrapper) return
    if (isOpen.value) {
      wrapper.removeAttribute('inert')
    } else {
      wrapper.setAttribute('inert', '')
      const origin = toggleOriginRef.current
      if (origin && wrapper.contains(document.activeElement)) origin.focus()
    }
  })

  const headerEl =
    isValidElement(header) && nav
      ? cloneElement(header as ReactElement<HeaderMenuProps>, {
          onMenuClick: toggle,
          menuExpanded: isOpen.value,
        })
      : header

  return (
    <div className={cn(styles['shell'], className)} data-open={isOpen.value} {...props}>
      <div className={styles['header']}>{headerEl}</div>
      <div className={styles['body']}>
        {nav && (
          <>
            <div
              ref={navWrapperRef}
              className={styles['navWrapper']}
              data-open={isOpen.value}
              data-testid="app-shell-nav"
              /* Stable styling hook. The wrapper carries only a hashed CSS-module class,
                 so a consumer who needs to reach it has no selector but
                 `div:has(> div > nav[aria-label='…'])` — which an adopter actually wrote,
                 and which breaks the moment the internal nesting changes (2026-07-28
                 report C14). This attribute is public API: see docs/STYLING-INTERNALS.md. */
              data-cascivo-appshell-nav=""
            >
              <div className={styles['navInner']}>{nav}</div>
            </div>
            <div
              className={styles['scrim']}
              data-open={isOpen.value}
              data-testid="app-shell-scrim"
              aria-hidden="true"
              onClick={() => setOpen(false)}
            />
          </>
        )}
        <main
          id="cascade-main"
          tabIndex={-1}
          className={styles['main']}
          data-cascivo-appshell-main=""
          data-padding={padding === 'none' ? 'none' : String(padding)}
        >
          {children}
        </main>
      </div>
      {footer && <div className={styles['footer']}>{footer}</div>}
    </div>
  )
}

@layer cascivo.component {
  /* Outer: one viewport-tall, non-scrolling flex column. The header is pinned
     (first, non-growing row); the body holds the only scroll container. */
  .shell {
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    block-size: 100vh; /* fallback for browsers without dvh */
    block-size: 100dvh;
    overflow: hidden;
    font-family: var(--cascivo-font-sans);
    color: var(--cascivo-color-foreground);
    background-color: var(--cascivo-color-background);
  }

  .header {
    flex: 0 0 auto;
    z-index: var(--cascivo-z-raised);
  }

  .body {
    position: relative; /* anchors the mobile drawer + scrim */
    flex: 1 1 auto;
    min-block-size: 0; /* let children own the scroll instead of growing the row */
    display: flex;
  }

  /* Base (mobile-first, < lg): the nav is an off-canvas drawer that slides in
     over the content. It never uses display:none, so it stays in the a11y tree
     and is reachable when open; `inert` (set in JS when closed) removes it from
     the tab order. */
  .navWrapper {
    position: absolute;
    inset-block: 0;
    inset-inline-start: 0;
    z-index: var(--cascivo-z-overlay);
    block-size: 100%;
    overflow: hidden;
    transform: translateX(-100%);
    transition: transform var(--cascivo-motion-emphasis);
  }

  .navWrapper[data-open='true'] {
    transform: translateX(0);
  }

  /* RTL: the drawer enters from the inline-end side. */
  :dir(rtl) .navWrapper {
    transform: translateX(100%);
  }

  :dir(rtl) .navWrapper[data-open='true'] {
    transform: translateX(0);
  }

  /* navInner is pinned to the nav's own width so, while the wrapper width
     animates to 0 (desktop), the contents clip/slide rather than reflow. */
  .navInner {
    display: flex;
    block-size: 100%;
    inline-size: var(--cascivo-shell-panel-inline-size, 20rem);
  }

  .navInner > * {
    flex: 1 1 auto;
    min-block-size: 0;
  }

  /* Rail collapse: the nav's own `data-state` drives the column, so AppShell's
     show/hide and SideNav's rail genuinely compose on different axes instead of
     AppShell always winning. Without this, `.navInner`'s pinned width plus the
     `flex: 1 1 auto` above stretched a collapsed 4rem SideNav back to the full
     18rem, leaving 24px icons in dead space and making the collapse control look
     inert (2026-08-31 report §14, measured 288 -> 288).

     The child selector is deliberate — only the nav AppShell was handed sits at
     `.navInner > *`, so a Collapsible *inside* the nav can carry the same
     `data-state="collapsed"` without resizing the column. */
  .navInner:has(> [data-state='collapsed']) {
    inline-size: var(--cascivo-sidenav-rail-inline-size, 4rem);
  }

  /* Scrim: only visible behind the open drawer on small screens. */
  .scrim {
    position: absolute;
    inset: 0;
    z-index: var(--cascivo-z-dropdown);
    background-color: oklch(0 0 0 / 0.4);
    opacity: 0;
    visibility: hidden;
    transition:
      opacity var(--cascivo-motion-emphasis),
      visibility var(--cascivo-motion-emphasis);
  }

  .scrim[data-open='true'] {
    opacity: 1;
    visibility: visible;
  }

  .main {
    flex: 1 1 auto;
    min-inline-size: 0;
    overflow-y: auto; /* the single scroll container */

    /* Content inset. Defaults to step 6 rather than 0 — see AppShell's `padding` prop for
       why (three reports of clipped first screenshots). `[data-padding='none']` opts out. */
    padding: var(--cascivo-space-6);
  }

  .main[data-padding='none'] {
    padding: 0;
  }
  .main[data-padding='1'] {
    padding: var(--cascivo-space-1);
  }
  .main[data-padding='2'] {
    padding: var(--cascivo-space-2);
  }
  .main[data-padding='3'] {
    padding: var(--cascivo-space-3);
  }
  .main[data-padding='4'] {
    padding: var(--cascivo-space-4);
  }
  .main[data-padding='5'] {
    padding: var(--cascivo-space-5);
  }
  .main[data-padding='6'] {
    padding: var(--cascivo-space-6);
  }
  .main[data-padding='8'] {
    padding: var(--cascivo-space-8);
  }
  .main[data-padding='10'] {
    padding: var(--cascivo-space-10);
  }
  .main[data-padding='12'] {
    padding: var(--cascivo-space-12);
  }

  .footer {
    flex: 0 0 auto;
  }

  /* Desktop (>= lg, 64rem): the nav becomes an in-flow column. Full-hide
     animates the wrapper's inline-size between its open width and 0 (explicit
     lengths — never the grid 1fr→0fr trick, which silently fails on an
     auto-width flex item). The pinned navInner clips as the wrapper closes.

     viewport-query: AppShell is the page frame — nothing contains it to query against, and
     drawer-vs-column is a device decision, not a slot one. */
  @media (min-width: 64rem) {
    .navWrapper {
      position: static;
      z-index: auto;
      inline-size: var(--cascivo-shell-aside-inline-size, 18rem);
      /* The sidebar has a fixed width by design, so it must never be the flex item that
         gives way. Without this it keeps the default `flex-shrink: 1` + `min-width: auto`,
         and an intrinsically-wide page shrinks the SIDEBAR instead of scrolling the
         content — while navInner (pinned to its own width) overflows the shrunken wrapper,
         so nothing looks broken and the page just sits narrower than every other page.
         Measured at 1700px: 268px against 288px on eight sibling routes (2026-07-28 report
         C14). Note `.main` already has `min-inline-size: 0`; that is not the fix, because
         main is not the element giving way. */
      flex-shrink: 0;
      transform: none;
      transition: inline-size var(--cascivo-motion-emphasis);
    }

    .navWrapper:has(> .navInner > [data-state='collapsed']) {
      inline-size: var(--cascivo-sidenav-rail-inline-size, 4rem);
    }

    /* Full-hide always wins over the rail width. Both selectors are needed: `:has()`
       takes the specificity of its most specific argument, so the rule above outranks a
       bare `[data-open='false']` no matter where it sits in source order. */
    .navWrapper[data-open='false'],
    .navWrapper[data-open='false']:has(> .navInner > [data-state='collapsed']) {
      inline-size: 0;
    }

    .navInner {
      inline-size: var(--cascivo-shell-aside-inline-size, 18rem);
      transition: inline-size var(--cascivo-motion-emphasis);
    }

    :dir(rtl) .navWrapper,
    :dir(rtl) .navWrapper[data-open='true'] {
      transform: none;
    }

    /* No scrim on desktop — the sidebar sits beside the content. */
    .scrim {
      display: none;
    }
  }
}

